/-- Fix [the probability law p](hyp:p). [Scalar total variation from the public uniform law on the paired alphabet](goal). -/
def tvFromUniform (p : Measure (PairedSymbol d)) : ℝ :=
  (1/2 : ℝ) * ∑ v : PairedSymbol d, |p.real {v} - 1/(2*d)|

