/-- Fix [the probability law P](hyp:P). [First-best population value](goal). -/
def value (P : Measure (FullRecord d)) : ℝ :=
  (d : ℝ)⁻¹ * ∑ j, max (armMean P false j) (armMean P true j) -- @realizes V(mean arm maximum)

